async function analyze(request, env) {
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return jsonResponse({ error: "Invalid request." }, 400);
  }
  const resume = String((body && body.resume) || "")
    .slice(0, 12000)
    .trim();
  const job = String((body && body.job) || "")
    .slice(0, 8000)
    .trim();
  if (!resume || !job)
    return jsonResponse(
      { error: "Please provide both your resume and the job description." },
      400,
    );
  let result;
  try {
    result = await env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        {
          role: "user",
          content:
            "JOB DESCRIPTION:\n" + job + "\n\nCANDIDATE RESUME:\n" + resume,
        },
      ],
      max_tokens: 3400,
      temperature: 0.35,
      response_format: { type: "json_object" },
    });
  } catch (e) {
    return jsonResponse(
      {
        error: "The AI model is busy right now. Please try again in a moment.",
      },
      502,
    );
  }
  const raw = result && result.response;
  let parsed = raw && typeof raw === "object" ? raw : null;
  const text = typeof raw === "string" ? raw : "";
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (!parsed && start !== -1 && end > start) {
    try {
      parsed = JSON.parse(sanitizeJson(text.slice(start, end + 1)));
    } catch (e) {
      parsed = null;
    }
  }
  if (!parsed || !parsed.rewritten_resume)
    return jsonResponse(
      { error: "The analysis came back incomplete. Please try again." },
      502,
    );
  return jsonResponse({
    score: parsed.score,
    subscores: parsed.subscores && typeof parsed.subscores === "object" ? parsed.subscores : {},
    verdict: parsed.verdict || "",
    recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations : [],
    rewrite_changes: Array.isArray(parsed.rewrite_changes) ? parsed.rewrite_changes : [],
    keyword_coverage: Array.isArray(parsed.keyword_coverage) ? parsed.keyword_coverage : [],
    fluff_detector: Array.isArray(parsed.fluff_detector) ? parsed.fluff_detector : [],
    recruiter_view: parsed.recruiter_view && typeof parsed.recruiter_view === "object" ? parsed.recruiter_view : {},
    rewritten_resume: parsed.rewritten_resume,
    job_title: parsed.job_title || "",
    company: parsed.company || "",
  });
}
// ---------- Shared AI helper ----------
const MODEL = "@cf/meta/llama-3.3-70b-instruct-fp8-fast";
const TRUTH_RULES =
  "Truthfulness rules you must follow: NEVER invent experience, employers, job titles, dates, metrics, numbers, tools, certifications or achievements that are not in the candidate's resume. Rephrase, reorder and re-emphasise only what is there. If the job asks for something the resume does not show, name it as a gap honestly or say 'only if true'. Never tell the candidate to add unverified facts or fake metrics.";
const JSON_RULES =
  " Respond with ONLY one valid JSON object that JSON.parse can read. Every property name and string value in double quotes, no trailing commas, no markdown fences, no text before or after.";
async function readBody(request) {
  try { return await request.json(); } catch (e) { return null; }
}
function clip(s, n) { return String(s || "").slice(0, n).trim(); }
function parseAiJson(result) {
  const raw = result && result.response;
  if (raw && typeof raw === "object") return raw;
  const text = typeof raw === "string" ? raw : "";
  const s = text.indexOf("{"), e = text.lastIndexOf("}");
  if (s === -1 || e <= s) return null;
  try { return JSON.parse(sanitizeJson(text.slice(s, e + 1))); } catch (err) { return null; }
}
async function aiJson(env, system, user, maxTokens, temperature) {
  let lastErr = null;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const result = await env.AI.run(MODEL, {
        messages: [{ role: "system", content: system + JSON_RULES }, { role: "user", content: user }],
        max_tokens: maxTokens || 1800,
        temperature: temperature == null ? 0.4 : temperature,
        response_format: { type: "json_object" },
      });
      const parsed = parseAiJson(result);
      if (parsed) return parsed;
      lastErr = new Error("incomplete");
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error("AI failed");
}
function arr(x) { return Array.isArray(x) ? x : []; }
function aiError(e) {
  return jsonResponse({ error: e && e.message === "incomplete" ? "The AI reply came back incomplete. Please try again." : "The AI model is busy right now. Please try again in a moment." }, 502);
}

// ---------- Cover letter ----------
async function coverLetter(request, env) {
  const b = await readBody(request);
  const resume = clip(b && b.resume, 12000), job = clip(b && b.job, 8000);
  const tone = ["professional", "warm", "confident", "concise"].indexOf(b && b.tone) >= 0 ? b.tone : "professional";
  const length = ["short", "standard"].indexOf(b && b.length) >= 0 ? b.length : "standard";
  if (!resume || !job) return jsonResponse({ error: "Upload a resume and add the job description first." }, 400);
  const system =
    "You are a senior recruiter who writes cover letters that hiring managers actually read. Write a cover letter for this candidate and this job. " + TRUTH_RULES +
    " Style: " + tone + " tone, plain modern English, no cliches (never 'I am writing to express my interest', 'passionate', 'hard-working', 'team player', 'synergy', 'leverage'). Open with a specific hook tied to the company or role. Middle: 2-3 concrete proofs taken from the resume that map to the job's top requirements. Close with a short, confident call to action. " +
    (length === "short" ? "Keep the body to 150-200 words." : "Keep the body to 250-320 words.") +
    " Use the company name and role title from the job description when present. Do not include a postal address block or date. Use keys exactly: {\"subject\": short email subject line for sending this application, \"greeting\": e.g. \"Dear Hiring Manager,\" or a named greeting only if a name appears in the job text, \"paragraphs\": array of 3-5 paragraph strings, \"sign_off\": e.g. \"Best regards,\", \"candidate_name\": the candidate's name from the resume or \"\", \"requirements_matched\": array of 3-5 short strings naming which job requirement each proof covers, \"gaps_not_claimed\": array of 0-3 short strings naming job requirements the letter deliberately did not claim because the resume does not show them}";
  try {
    const p = await aiJson(env, system, "JOB DESCRIPTION:\n" + job + "\n\nCANDIDATE RESUME:\n" + resume, 1400, 0.55);
    const paragraphs = arr(p.paragraphs).map(String).filter(Boolean);
    if (!paragraphs.length) throw new Error("incomplete");
    return jsonResponse({ subject: p.subject || "", greeting: p.greeting || "Dear Hiring Manager,", paragraphs, sign_off: p.sign_off || "Best regards,", candidate_name: p.candidate_name || "", requirements_matched: arr(p.requirements_matched), gaps_not_claimed: arr(p.gaps_not_claimed) });
  } catch (e) { return aiError(e); }
}

