async function interviewPrep(request, env) {
  const b = await readBody(request);
  const resume = clip(b && b.resume, 12000), job = clip(b && b.job, 8000);
  if (!resume || !job) return jsonResponse({ error: "Upload a resume and add the job description first." }, 400);
  const system =
    "You are an interview coach and former hiring manager. Predict the questions this candidate is most likely to face for this exact job, based on the job description and the candidate's resume. " + TRUTH_RULES +
    " Answer outlines must only use stories and facts that are in the resume; when the resume has no matching story, say so and suggest how to answer honestly (transferable experience or a learning plan). Use keys exactly: {\"role_summary\": one sentence on what this interviewer will be testing, \"questions\": array of 10-12 objects each exactly {\"category\": one of \"Behavioral\", \"Role-specific\", \"Technical\", \"Resume deep-dive\", \"Culture & motivation\", \"question\": the question, \"why_asked\": short reason the interviewer asks it for this job, \"answer_outline\": 2-4 sentence STAR-style outline built from the resume, \"resume_evidence\": the exact resume line or project to cite, or \"none in resume\"}, \"weak_spots\": array of 2-4 objects each exactly {\"topic\": gap or risk area an interviewer will probe, \"how_to_handle\": one honest way to handle it}, \"questions_to_ask\": array of 3 smart questions the candidate can ask the interviewer about this role}";
  try {
    const p = await aiJson(env, system, "JOB DESCRIPTION:\n" + job + "\n\nCANDIDATE RESUME:\n" + resume, 3000, 0.45);
    const qs = arr(p.questions).filter((q) => q && q.question);
    if (!qs.length) throw new Error("incomplete");
    return jsonResponse({ role_summary: p.role_summary || "", questions: qs, weak_spots: arr(p.weak_spots), questions_to_ask: arr(p.questions_to_ask) });
  } catch (e) { return aiError(e); }
}

// ---------- LinkedIn optimizer ----------
async function linkedinOptimize(request, env) {
  const b = await readBody(request);
  const resume = clip(b && b.resume, 12000), profile = clip(b && b.profile, 6000), target = clip(b && b.target, 200);
  if (!resume) return jsonResponse({ error: "Upload a resume first - the optimizer uses it as the source of truth." }, 400);
  const system =
    "You are a LinkedIn profile strategist who knows how recruiters search LinkedIn Recruiter (headline and skills keywords, About section, experience bullets). Optimize this person's LinkedIn profile for the target role. " + TRUTH_RULES +
    " Use keys exactly: {\"profile_score\": integer 0-100 for how well the current profile (or resume, if no profile text given) would surface in recruiter searches for the target role, \"headlines\": array of 3 headline options, each 120-220 characters, in the pattern target role | 2-3 evidenced specialties | one concrete proof point from the resume, keyword-rich but human, \"about\": a first-person About section of 150-260 words with line breaks as \\n, ending with what roles they are open to, \"top_skills\": array of 10-15 skills to list, ordered by recruiter search value for the target role, only skills evidenced in the resume, \"missing_keywords\": array of 3-8 target-role keywords the profile lacks, to add only if true, \"experience_rewrites\": array of 2-4 objects each exactly {\"role\": role and company from the resume, \"bullets\": array of 2-4 LinkedIn-ready bullets}, \"quick_wins\": array of 4-6 short specific actions (e.g. Open to Work settings, custom URL, featured section) tailored to this person}";
  const user = "TARGET ROLE: " + (target || "the role the resume points to") + "\n\nCURRENT LINKEDIN PROFILE TEXT (may be empty):\n" + (profile || "(not provided)") + "\n\nRESUME:\n" + resume;
  try {
    const p = await aiJson(env, system, user, 2600, 0.5);
    if (!arr(p.headlines).length && !p.about) throw new Error("incomplete");
    return jsonResponse({ profile_score: p.profile_score, headlines: arr(p.headlines), about: p.about || "", top_skills: arr(p.top_skills), missing_keywords: arr(p.missing_keywords), experience_rewrites: arr(p.experience_rewrites), quick_wins: arr(p.quick_wins) });
  } catch (e) { return aiError(e); }
}

// ---------- Quick score (bulk compare) ----------
async function quickScore(request, env) {
  const b = await readBody(request);
  const resume = clip(b && b.resume, 12000), job = clip(b && b.job, 6000);
  if (!resume || !job) return jsonResponse({ error: "Missing resume or job description." }, 400);
  const system =
    "You are an ATS specialist and recruiter. Score how well this resume matches this one job. Be calibrated and strict: 80+ only for a near-exact fit. " + TRUTH_RULES +
    " Use keys exactly: {\"job_title\": role title from the job text, \"company\": company name or \"\", \"location\": location or \"\", \"score\": integer 0-100, \"subscores\": {\"skills\": 0-100, \"experience\": 0-100, \"keywords\": 0-100}, \"verdict\": one short sentence, \"strengths\": array of 2-3 short phrases, \"missing\": array of 2-4 short phrases naming the most important missing requirements or keywords, \"apply_advice\": one of \"Apply now\", \"Tailor first\", \"Stretch\", \"Skip\"}";
  try {
    const p = await aiJson(env, system, "JOB DESCRIPTION:\n" + job + "\n\nRESUME:\n" + resume, 600, 0.2);
    if (p.score == null) throw new Error("incomplete");
    return jsonResponse({ job_title: p.job_title || "", company: p.company || "", location: p.location || "", score: p.score, subscores: p.subscores || {}, verdict: p.verdict || "", strengths: arr(p.strengths), missing: arr(p.missing), apply_advice: p.apply_advice || "" });
  } catch (e) { return aiError(e); }
}

// ---------- Salary insights ----------
function toAnnualInr(text) {
  // Parse one salary string into [min,max] annual INR, or null.
  let s = String(text || "").toLowerCase().replace(/,/g, "");
  if (!s) return null;
  const isInr = /₹|inr|rs\.?|lpa|lakh|lac|crore/.test(s);
  const isUsd = /\$|usd/.test(s);
  if (!isInr && !isUsd) return null;
  let mult = 1;
  if (/lpa|lakh|lac|\bl\b/.test(s)) mult = 100000;
  if (/crore|\bcr\b/.test(s)) mult = 10000000;
  let period = 1;
  if (/month|\/mo|per mo|pm\b|monthly/.test(s)) period = 12;
  else if (/hour|\/hr|per hr/.test(s)) period = 2000;
  const nums = (s.match(/\d+(?:\.\d+)?\s*k?/g) || []).map((n) => {
    let v = parseFloat(n);
    if (/k$/.test(n.trim())) v *= 1000;
    return v;
  }).filter((v) => v > 0);
  if (!nums.length) return null;
  let lo = nums[0], hi = nums[1] && nums[1] >= lo ? nums[1] : nums[0];
  lo *= mult * period; hi *= mult * period;
  if (isUsd && !isInr) { lo *= 83; hi *= 83; }
  if (hi < 60000 || lo > 50000000) return null; // implausible
  return [lo, hi];
}
function pct(sorted, p) {
  if (!sorted.length) return null;
  const i = (sorted.length - 1) * p, lo = Math.floor(i), hi = Math.ceil(i);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (i - lo);
}
async function salaryInsights(request, env) {
  const b = await readBody(request);
  const job = clip(b && b.job, 8000), resume = clip(b && b.resume, 6000);
  if (!job) return jsonResponse({ error: "Add a job description first." }, 400);
  let meta;
  try {
    meta = await aiJson(env,
      "You extract facts from a job description and give a cautious Indian salary estimate. Use keys exactly: {\"job_title\": normalized role title, \"search_title\": 2-4 word generic title to search job boards (e.g. \"product manager\"), \"company\": company or \"\", \"location\": city or \"Remote\" or \"India\", \"seniority\": one of \"Entry\", \"Mid\", \"Senior\", \"Lead\", \"experience_years\": string like \"0-2\" or \"\", \"disclosed_salary\": the exact salary text if the job description states pay, else \"\", \"estimate_lpa_low\": number, \"estimate_lpa_high\": number (your estimated annual fixed CTC range in lakhs INR for this role, level, company type and location in the Indian market; if the job is clearly outside India, convert its local market range to lakhs INR), \"estimate_basis\": one short sentence on what drove the estimate, \"negotiation_tips\": array of 3 short tips specific to this role}",
      "JOB DESCRIPTION:\n" + job + (resume ? "\n\nCANDIDATE RESUME (for experience level only):\n" + resume : ""), 700, 0.2);
  } catch (e) { return aiError(e); }
  const q = String(meta.search_title || meta.job_title || "").slice(0, 60);
  const samples = [];
  const tasks = [];
  if (q && env.JOOBLE_API_KEY) {
    for (const location of [meta.location && !/remote/i.test(meta.location) ? meta.location : "India", "India"]) {
      tasks.push(fetch("https://in.jooble.org/api/" + env.JOOBLE_API_KEY, {
        method: "POST", headers: { "content-type": "application/json", "User-Agent": UA },
        body: JSON.stringify({ keywords: q, location, page: "1" }),
      }).then((r) => (r.ok ? r.json() : null)).then((d) => {
        for (const j of arr(d && d.jobs)) {
          const r = toAnnualInr(j.salary);
          if (r) samples.push({ title: j.title || "", company: j.company || "", location: j.location || "", url: j.link || "", salary_text: j.salary, lo: r[0], hi: r[1], source: "Jooble India" });
        }
      }).catch(() => {}));
    }
  }
  await Promise.all(tasks);
  const seen = new Set();
  const uniq = samples.filter((s) => { const k = s.url || s.title + s.company; if (seen.has(k)) return false; seen.add(k); return true; });
  const mids = uniq.map((s) => (s.lo + s.hi) / 2).sort((a, b) => a - b);
  const market = mids.length >= 3 ? { count: mids.length, p25: pct(mids, 0.25), median: pct(mids, 0.5), p75: pct(mids, 0.75) } : null;
  const disclosed = meta.disclosed_salary ? { text: meta.disclosed_salary, range: toAnnualInr(meta.disclosed_salary) } : null;
  const lo = parseFloat(meta.estimate_lpa_low), hi = parseFloat(meta.estimate_lpa_high);
  return jsonResponse({
    job_title: meta.job_title || "", company: meta.company || "", location: meta.location || "", seniority: meta.seniority || "", experience_years: meta.experience_years || "",
    disclosed,
    market,
    market_samples: uniq.slice(0, 8).map((s) => ({ title: s.title, company: s.company, location: s.location, url: s.url, salary_text: s.salary_text })),
    ai_estimate: isFinite(lo) && isFinite(hi) && hi > 0 ? { low_lpa: lo, high_lpa: hi, basis: meta.estimate_basis || "" } : null,
    negotiation_tips: arr(meta.negotiation_tips),
    search_title: q,
  });
}

// ---------- Referral message ----------
async function referralMessage(request, env) {
  const b = await readBody(request);
  const resume = clip(b && b.resume, 6000), job = clip(b && b.job, 4000);
  const person = clip(b && b.person, 120), relation = ["first", "second", "stranger"].indexOf(b && b.relation) >= 0 ? b.relation : "second";
  if (!resume || !job) return jsonResponse({ error: "Upload a resume and add the job description first." }, 400);
  const system =
    "You write short LinkedIn referral requests that get replies. The message is written BY the candidate (first person, I/me) directly TO the recipient, asking the recipient to refer the candidate. Sign off with the candidate's first name from the resume. " + TRUTH_RULES +
    " The message must be under 300 characters for a connection note when relation is second or stranger, and under 700 characters for a first-degree message. Be specific about the role, mention one real, relevant strength from the resume, make it easy to say yes (offer to send resume + job link), no guilt, no flattery. Use keys exactly: {\"connection_note\": message under 300 characters, \"message\": a slightly longer version under 700 characters, \"follow_up\": a polite follow-up under 250 characters to send after 4-5 days of no reply}";
  try {
    const p = await aiJson(env, system, "RECIPIENT: " + (person || "an employee at the company") + " (relation: " + relation + " degree)\n\nJOB:\n" + job + "\n\nRESUME:\n" + resume, 600, 0.6);
    return jsonResponse({ connection_note: p.connection_note || "", message: p.message || "", follow_up: p.follow_up || "" });
  } catch (e) { return aiError(e); }
}

// ---------- Chrome extension download ----------
async function extensionZip() {
  const bin = Uint8Array.from(atob(EXT_ZIP_B64), (c) => c.charCodeAt(0));
  return new Response(bin, { headers: { "content-type": "application/zip", "content-disposition": 'attachment; filename="resumefit-extension.zip"', "cache-control": "no-cache" } });
}

export default {
  async fetch(request, env) {
    if (request.method === "GET") {
      const p = new URL(request.url).pathname;
      if (p === "/" || p === "/index.html")
        return new Response(await getHtml(), {
          headers: {
            "content-type": "text/html; charset=utf-8",
            "cache-control": "no-cache",
          },
        });
    }
    const url = new URL(request.url);
    if (request.method === "OPTIONS")
      return new Response(null, {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
          "Access-Control-Allow-Headers": "content-type",
        },
      });
    if (request.method === "POST" && url.pathname === "/api/analyze")
      return analyze(request, env);
    if (request.method === "GET" && url.pathname === "/api/jobs")
      return fetchJobs(request, env);
    if (request.method === "POST" && url.pathname === "/api/fetch-jd")
      return fetchJd(request);
    if (request.method === "POST" && url.pathname === "/api/cover-letter")
      return coverLetter(request, env);
    if (request.method === "POST" && url.pathname === "/api/interview")
      return interviewPrep(request, env);
    if (request.method === "POST" && url.pathname === "/api/linkedin")
      return linkedinOptimize(request, env);
    if (request.method === "POST" && url.pathname === "/api/quick-score")
      return quickScore(request, env);
    if (request.method === "POST" && url.pathname === "/api/salary")
      return salaryInsights(request, env);
    if (request.method === "POST" && url.pathname === "/api/referral-message")
      return referralMessage(request, env);
    if (request.method === "GET" && url.pathname === "/extension.zip")
      return extensionZip();
    return new Response("ResumeFit API", { status: 200 });
  },
};
